int main() {
    int N, M, K;
    scanf("%d %d %d", &N, &M, &K);

    long long *w = malloc((N+1) * sizeof(long long));
    for (int i = 1; i <= N; i++) scanf("%lld", &w[i]);

    int *a = malloc(K * sizeof(int));
    for (int i = 0; i < K; i++) scanf("%d", &a[i]);

    // For each position, compute next use
    int *next_use = malloc(K * sizeof(int));
    int *last_seen = malloc((N+1) * sizeof(int));
    for (int i = 1; i <= N; i++) last_seen[i] = INF;

    for (int i = K-1; i >= 0; i--) {
        next_use[i] = last_seen[a[i]];
        last_seen[a[i]] = i;
    }

    // Simulate cache
    int *cache = malloc(M * sizeof(int));   // ball numbers in cache
    int *next_use_cache = malloc(M * sizeof(int)); // their next use
    int cache_size = 0;

    // Use a simple lookup: in_cache[ball] = index in cache array, or -1
    int *in_cache = malloc((N+1) * sizeof(int));
    memset(in_cache, -1, (N+1) * sizeof(int));

    long long total_cost = 0;

    for (int i = 0; i < K; i++) {
        int ball = a[i];
        if (in_cache[ball] != -1) {
            // Cache hit, update next_use
            int idx = in_cache[ball];
            next_use_cache[idx] = next_use[i];
        } else {
            // Cache miss
            total_cost += w[ball];
            if (cache_size < M) {
                cache[cache_size] = ball;
                next_use_cache[cache_size] = next_use[i];
                in_cache[ball] = cache_size;
                cache_size++;
            } else {
                // Find eviction candidate: max next_use
                int evict_idx = 0;
                for (int j = 1; j < M; j++) {
                    if (next_use_cache[j] > next_use_cache[evict_idx]) evict_idx = j;
                }
                in_cache[cache[evict_idx]] = -1;
                cache[evict_idx] = ball;
                next_use_cache[evict_idx] = next_use[i];
                in_cache[ball] = evict_idx;
            }
        }
    }

    printf("%lld\n", total_cost);

    free(w); free(a); free(next_use); free(last_seen);
    free(cache); free(next_use_cache); free(in_cache);
    return 0;
}

