typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int M, N, K;
    if (scanf("%d %d %d", &M, &N, &K) != 3) return 0;

    ll *w = (ll *)malloc((N + 1) * sizeof(ll));
    for (int i = 1; i <= N; i++) scanf("%lld", &w[i]);

    int *a = (int *)malloc(K * sizeof(int));
    int *cnt = (int *)calloc(N + 1, sizeof(int));

    for (int i = 0; i < K; i++) {
        scanf("%d", &a[i]);
        cnt[a[i]]++;
    }

    /* If cache can hold all distinct balls, each ball is loaded at most once. */
    if (M >= N) {
        ll ans = 0;
        for (int i = 1; i <= N; i++) {
            if (cnt[i] > 0) ans += w[i];
        }
        printf("%lld\n", ans);
        free(w); free(a); free(cnt);
        return 0;
    }

    /*
      Optimal offline strategy (Belady):
      A miss occurs when requested ball is not currently cached; on a miss we pay its weight.
      With full foresight, to minimize future misses we keep in cache the M balls whose
      next use is earliest? Equivalently, evict the one used farthest in future.

      This can be transformed into:
      For each occurrence except the last of a ball, there is a "reuse interval"
      between this occurrence and the next one. If we keep the ball in cache through
      that interval, we avoid paying its weight at the next occurrence.
      At any time, at most M balls can be in cache, but one slot is occupied by the
      currently requested ball during its own interval transitions, so among active
      reuse intervals we can keep at most M-1 simultaneously.

      Therefore maximize total saved weight by selecting active intervals with capacity M-1.
      Standard sweep: each interval [l, r) with value w. Maintain chosen active intervals;
      if active chosen exceed capacity, drop the smallest weight.
    */

    int *occPos = (int *)malloc(K * sizeof(int));
    int *head = (int *)malloc((N + 1) * sizeof(int));
    int *nextIdx = (int *)malloc(K * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    for (int i = K - 1; i >= 0; i--) {
        int x = a[i];
        nextIdx[i] = head[x];
        head[x] = i;
    }

    ll totalCost = 0;
    for (int i = 0; i < K; i++) totalCost += w[a[i]];

    if (M == 0) {
        printf("%lld\n", totalCost);
        free(w); free(a); free(cnt); free(occPos); free(head); free(nextIdx);
        return 0;
    }

    int intervalCount = 0;
    for (int i = 0; i < K; i++) {
        if (nextIdx[i] != -1) intervalCount++;
    }

    typedef struct {
        int l, r;
        ll val;
        int id;
    } Interval;

    Interval *intervals = (Interval *)malloc(intervalCount * sizeof(Interval));
    int *startCnt = (int *)calloc(K + 1, sizeof(int));
    int *endCnt = (int *)calloc(K + 1, sizeof(int));

    int id = 0;
    for (int i = 0; i < K; i++) {
        if (nextIdx[i] != -1) {
            intervals[id].l = i + 1;          // active after current access
            intervals[id].r = nextIdx[i];     // until just before next access point
            intervals[id].val = w[a[i]];
            intervals[id].id = id;
            startCnt[intervals[id].l]++;
            endCnt[intervals[id].r]++;
            id++;
        }
    }

    int *startOff = (int *)malloc((K + 2) * sizeof(int));
    int *endOff = (int *)malloc((K + 2) * sizeof(int));
    startOff[0] = 0;
    endOff[0] = 0;
    for (int i = 0; i <= K; i++) {
        startOff[i + 1] = startOff[i] + startCnt[i];
        endOff[i + 1] = endOff[i] + endCnt[i];
    }

    int *startList = (int *)malloc(intervalCount * sizeof(int));
    int *endList = (int *)malloc(intervalCount * sizeof(int));
    int *curS = (int *)calloc(K + 1, sizeof(int));
    int *curE = (int *)calloc(K + 1, sizeof(int));

    for (int i = 0; i < intervalCount; i++) {
        int l = intervals[i].l;
        int r = intervals[i].r;
        startList[startOff[l] + curS[l]++] = i;
        endList[endOff[r] + curE[r]++] = i;
    }

    /* Two-heaps lazy deletion:
       chosen min-heap by value, unchosen max-heap by value.
       status: 0 inactive, 1 chosen, 2 active unchosen
    */
    int cap = M - 1;
    if (cap < 0) cap = 0;

    int *status = (int *)calloc(intervalCount, sizeof(int));

    int *minHeap = (int *)malloc((intervalCount + 5) * sizeof(int));
    int minSz = 0;
    int *maxHeap = (int *)malloc((intervalCount + 5) * sizeof(int));
    int maxSz = 0;

    #define LESS_MIN(i,j) (intervals[(i)].val < intervals[(j)].val || (intervals[(i)].val == intervals[(j)].val && (i) < (j)))
    #define LESS_MAX(i,j) (intervals[(i)].val > intervals[(j)].val || (intervals[(i)].val == intervals[(j)].val && (i) < (j)))

    void min_push(int x) {
        int p = ++minSz;
        minHeap[p] = x;
        while (p > 1) {
            int q = p >> 1;
            if (!LESS_MIN(minHeap[p], minHeap[q])) break;
            int t = minHeap[p]; minHeap[p] = minHeap[q]; minHeap[q] = t;
            p = q;
        }
    }
    int min_top() { return minHeap[1]; }
    void min_pop() {
        minHeap[1] = minHeap[minSz--];
        int p = 1;
        while (1) {
            int l = p << 1, r = l + 1, b = p;
            if (l <= minSz && LESS_MIN(minHeap[l], minHeap[b])) b = l;
            if (r <= minSz && LESS_MIN(minHeap[r], minHeap[b])) b = r;
            if (b == p) break;
            int t = minHeap[p]; minHeap[p] = minHeap[b]; minHeap[b] = t;
            p = b;
        }
    }

    void max_push(int x) {
        int p = ++maxSz;
        maxHeap[p] = x;
        while (p > 1) {
            int q = p >> 1;
            if (!LESS_MAX(maxHeap[p], maxHeap[q])) break;
            int t = maxHeap[p]; maxHeap[p] = maxHeap[q]; maxHeap[q] = t;
            p = q;
        }
    }
    int max_top() { return maxHeap[1]; }
    void max_pop() {
        maxHeap[1] = maxHeap[maxSz--];
        int p = 1;
        while (1) {
            int l = p << 1, r = l + 1, b = p;
            if (l <= maxSz && LESS_MAX(maxHeap[l], maxHeap[b])) b = l;
            if (r <= maxSz && LESS_MAX(maxHeap[r], maxHeap[b])) b = r;
            if (b == p) break;
            int t = maxHeap[p]; maxHeap[p] = maxHeap[b]; maxHeap[b] = t;
            p = b;
        }
    }

    ll saved = 0;
    int chosenCnt = 0;

    void clean_min() {
        while (minSz > 0 && status[min_top()] != 1) min_pop();
    }
    void clean_max() {
        while (maxSz > 0 && status[max_top()] != 2) max_pop();
    }

    for (int t = 0; t < K; t++) {
        /* intervals ending here are no longer active before serving access t */
        for (int p = endOff[t]; p < endOff[t + 1]; p++) {
            int x = endList[p];
            if (status[x] == 1) {
                status[x] = 0;
                chosenCnt--;
                saved -= intervals[x].val;
            } else if (status[x] == 2) {
                status[x] = 0;
            }
        }

        clean_min();
        clean_max();

        /* fill vacancies from best unchosen active intervals */
        while (chosenCnt < cap) {
            clean_max();
            if (maxSz == 0) break;
            int x = max_top(); max_pop();
            if (status[x] != 2) continue;
            status[x] = 1;
            chosenCnt++;
            saved += intervals[x].val;
            min_push(x);
        }

        /* intervals starting now become active */
        for (int p = startOff[t]; p < startOff[t + 1]; p++) {
            int x = startList[p];
            if (cap == 0) {
                status[x] = 2;
                max_push(x);
                continue;
            }
            clean_min();
            if (chosenCnt < cap) {
                status[x] = 1;
                chosenCnt++;
                saved += intervals[x].val;
                min_push(x);
            } else {
                if (chosenCnt > 0 && intervals[x].val > intervals[min_top()].val) {
                    int y = min_top(); min_pop();
                    if (status[y] == 1) {
                        status[y] = 2;
                        chosenCnt--;
                        saved -= intervals[y].val;
                        max_push(y);
                    }
                    status[x] = 1;
                    chosenCnt++;
                    saved += intervals[x].val;
                    min_push(x);
                } else {
                    status[x] = 2;
                    max_push(x);
                }
            }
        }
    }

    ll ans = totalCost - saved;
    printf("%lld\n", ans);

    free(w); free(a); free(cnt); free(occPos); free(head); free(nextIdx);
    free(intervals); free(startCnt); free(endCnt); free(startOff); free(endOff);
    free(startList); free(endList); free(curS); free(curE); free(status);
    free(minHeap); free(maxHeap);

    return 0;
}

