#include <bits/stdc++.h>
using namespace std;

/*
The statement is clearly the classic offline caching / Belady problem,
but written with "boxes" and "balls".

Interpretation used:
- There are M boxes = cache capacity M.
- Ball types are 1..N, each type i has loading cost w[i].
- A sequence of K requests asks for ball x.
- If x is already in some box, cost 0.
- Otherwise we must place it into a box, paying w[x].
  If all M boxes are occupied, we may evict any currently stored ball.
- All requests are known in advance, so optimal offline strategy is required.

Goal: minimize total paid cost.

Optimal strategy:
This is weighted paging / weighted caching.
At each miss, among currently cached items plus the requested one, one item
must be excluded from cache after serving this request.
For offline optimality, use dynamic programming over requests with a min-cost
matching style reduction that becomes a shortest path / min-cost flow on DAG.

A standard equivalent DP:
Let nextPos[t] = next occurrence position of request at time t, or INF if none.
Think of each miss creating an interval from current request position to its next use.
Keeping an item in cache occupies one slot over that interval and saves its reload cost
at the next use.

Thus total baseline cost = sum of weights of all requests.
Each time we keep an item from one request to its next request, we gain (save) w[item].
Need to choose a set of such intervals with at most M simultaneous intervals,
maximizing saved weight.

This is weighted interval scheduling with capacity M on overlaps.
Can be solved by min-cost max-flow on a DAG / equivalently maximum cost flow:
- Compress all request positions 1..K and K+1 sentinel.
- Add edges i -> i+1 with capacity M, cost 0.
- For every request position t whose next occurrence is u <= K,
  add edge t -> u with capacity 1 and cost = w[req[t]] (profit edge).
- Send M units of flow from 1 to K+1 maximizing profit.
Answer = baseline - maxProfit.

Why correct:
A unit of flow corresponds to one cache slot through time.
Taking profit edge t->u means this slot stores that ball from request t until next use u,
saving one future load of cost w.
Capacity M on timeline edges enforces at most M simultaneously stored balls.

We compute maximum profit with min-cost max-flow by negating costs.
Complexities:
Nodes O(K), edges O(K), flow M. Works well for typical constraints.
*/

struct Edge {
    int to, rev, cap;
    long long cost;
};

struct MinCostMaxFlow {
    int n;
    vector<vector<Edge>> g;
    MinCostMaxFlow(int n) : n(n), g(n) {}

    void addEdge(int s, int t, int cap, long long cost) {
        Edge a{t, (int)g[t].size(), cap, cost};
        Edge b{s, (int)g[s].size(), 0, -cost};
        g[s].push_back(a);
        g[t].push_back(b);
    }

    pair<int,long long> minCostMaxFlow(int s, int t, int maxf) {
        const long long INF = (1LL<<62);
        int flow = 0;
        long long cost = 0;
        vector<long long> pot(n, 0), dist(n);
        vector<int> pv(n), pe(n);

        while (flow < maxf) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
            pq.push({0, s});

            while (!pq.empty()) {
                auto [d, v] = pq.top();
                pq.pop();
                if (d != dist[v]) continue;
                for (int i = 0; i < (int)g[v].size(); ++i) {
                    const auto &e = g[v][i];
                    if (e.cap <= 0) continue;
                    long long nd = d + e.cost + pot[v] - pot[e.to];
                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        pq.push({nd, e.to});
                    }
                }
            }
            if (dist[t] == INF) break;
            for (int i = 0; i < n; ++i) {
                if (dist[i] < INF) pot[i] += dist[i];
            }

            int addf = maxf - flow;
            for (int v = t; v != s; v = pv[v]) {
                addf = min(addf, g[pv[v]][pe[v]].cap);
            }
            flow += addf;
            for (int v = t; v != s; v = pv[v]) {
                Edge &e = g[pv[v]][pe[v]];
                e.cap -= addf;
                g[v][e.rev].cap += addf;
                cost += 1LL * addf * e.cost;
            }
        }
        return {flow, cost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int M, N, K;
    cin >> M >> N >> K;

    vector<long long> w(N + 1);
    for (int i = 1; i <= N; ++i) cin >> w[i];

    vector<int> a(K + 1);
    for (int i = 1; i <= K; ++i) cin >> a[i];

    long long baseline = 0;
    for (int i = 1; i <= K; ++i) baseline += w[a[i]];

    const int INF = K + 1;
    vector<int> last(N + 1, INF), nxt(K + 1, INF);
    for (int i = K; i >= 1; --i) {
        nxt[i] = last[a[i]];
        last[a[i]] = i;
    }

    // Nodes: 1..K+1 mapped to 0..K
    int V = K + 1;
    MinCostMaxFlow mcmf(V);

    for (int i = 1; i <= K; ++i) {
        mcmf.addEdge(i - 1, i, M, 0); // timeline edge
    }

    for (int i = 1; i <= K; ++i) {
        if (nxt[i] <= K) {
            // profit edge; negate cost for min-cost flow
            mcmf.addEdge(i - 1, nxt[i] - 1, 1, -w[a[i]]);
        }
    }

    auto [flow, minCost] = mcmf.minCostMaxFlow(0, K, M);
    long long maxProfit = -minCost;
    long long answer = baseline - maxProfit;

    cout << answer << '\n';
    return 0;
}

