public class CacheStrategy {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int M = sc.nextInt(); // number of boxes (cache slots)
        int N = sc.nextInt(); // number of balls
        int K = sc.nextInt(); // length of sequence

        int[] weights = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            weights[i] = sc.nextInt();
        }

        int[] sequence = new int[K];
        for (int i = 0; i < K; i++) {
            sequence[i] = sc.nextInt();
        }

        // Precompute next occurrence for each position
        int[] nextOccurrence = new int[K];
        Map<Integer, Integer> nextIndex = new HashMap<>();
        for (int i = K - 1; i >= 0; i--) {
            int ball = sequence[i];
            nextOccurrence[i] = nextIndex.getOrDefault(ball, Integer.MAX_VALUE);
            nextIndex.put(ball, i);
        }

        Set<Integer> cache = new HashSet<>();
        // For priority queue: (nextUseIndex, ballId)
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]); // max-heap by next use

        int cost = 0;

        for (int i = 0; i < K; i++) {
            int ball = sequence[i];

            if (!cache.contains(ball)) {
                cost += weights[ball];

                if (cache.size() == M) {
                    // Evict ball with farthest next use
                    int[] evict = pq.poll();
                    cache.remove(evict[1]);
                }

                cache.add(ball);
            }

            // Update priority queue: remove old entry for this ball, add new one
            // Since we can't easily remove from PQ, we just add new and skip stale later
            pq.offer(new int[]{nextOccurrence[i], ball});

            // Clean stale entries from the top of PQ
            while (!pq.isEmpty() && !cache.contains(pq.peek()[1])) {
                pq.poll();
            }
        }

        System.out.println(cost);
    }
}

