        Scanner sc = new Scanner(System.in);
        int M = sc.nextInt(); // boxes (cache size)
        int N = sc.nextInt(); // balls
        int K = sc.nextInt(); // operations

        int[] weight = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            weight[i] = sc.nextInt();
        }

        int[] ops = new int[K];
        for (int i = 0; i < K; i++) {
            ops[i] = sc.nextInt();
        }

        // Precompute next occurrence for each position
        // nextUse[i] = next index after i where ops[i] is used again
        int[] nextUse = new int[K];
        Map<Integer, Integer> lastSeen = new HashMap<>();
        for (int i = K - 1; i >= 0; i--) {
            int ball = ops[i];
            nextUse[i] = lastSeen.getOrDefault(ball, K); // K means never
            lastSeen.put(ball, i);
        }

        // Simulate cache with Bélády's algorithm
        Set<Integer> cache = new HashSet<>();
        // For each ball in cache, we need to know its next use
        // Use a TreeMap: nextUse -> ball (to find the one with farthest next use)
        TreeMap<Integer, Integer> byNextUse = new TreeMap<>();
        Map<Integer, Integer> ballToNextUse = new HashMap<>();

        long totalCost = 0;

        for (int i = 0; i < K; i++) {
            int ball = ops[i];
            int nu = nextUse[i];

            if (cache.contains(ball)) {
                // Update next use
                int oldNu = ballToNextUse.get(ball);
                byNextUse.remove(oldNu);
                byNextUse.put(nu, ball);
                ballToNextUse.put(ball, nu);
            } else {
                // Cache miss
                totalCost += weight[ball];
                if (cache.size() == M) {
                    // Evict ball with farthest next use
                    Map.Entry<Integer, Integer> entry = byNextUse.lastEntry();
                    int evictBall = entry.getValue();
                    byNextUse.pollLastEntry();
                    ballToNextUse.remove(evictBall);
                    cache.remove(evictBall);
                }
                cache.add(ball);
                byNextUse.put(nu, ball);
                ballToNextUse.put(ball, nu);
            }
        }

        System.out.println(totalCost);
    }
}

