/*
Cache Strategy Problem

Interpretation:
- There are N items (balls), item i has loading cost w[i].
- Cache has capacity M (full associative).
- We know the whole access sequence of length K in advance.
- Accessing an item already in cache costs 0.
- Otherwise we must load it, paying its weight.
- If cache is full, evict one item.
- Need minimum total cost.

Optimal strategy:
Belady-style exchange argument still works for weighted misses because the miss cost
depends only on the requested item, not on the victim. On a miss, evict the cached item
whose next use is farthest in the future (or never used again).

DP/greedy simulation:
Process requests from back to front to know each occurrence's next position.
Then simulate from front:
- Maintain cache contents.
- For each cached item, key = next occurrence position after current one
  (INF if never used again).
- On miss:
  - if free space, insert
  - else evict item with maximum next-use key.
Data structure:
- TreeSet ordered by (nextPos, id), descending retrieval via last().
- Arrays track whether an item is in cache and its current nextPos key.

Complexities:
O(K log N)

Input format assumed from statement:
M N
w1 w2 ... wN
K
a1 a2 ... aK

This is the most natural format for the described problem.
*/
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Node implements Comparable<Node> {
        int nextPos;
        int id;

        Node(int nextPos, int id) {
            this.nextPos = nextPos;
            this.id = id;
        }

        public int compareTo(Node o) {
            if (nextPos != o.nextPos) return Integer.compare(nextPos, o.nextPos);
            return Integer.compare(id, o.id);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int M = fs.nextInt();
        int N = fs.nextInt();

        long[] w = new long[N + 1];
        for (int i = 1; i <= N; i++) w[i] = fs.nextInt();

        int K = fs.nextInt();
        int[] a = new int[K + 1];
        for (int i = 1; i <= K; i++) a[i] = fs.nextInt();

        final int INF = K + 1;

        int[] nextOccurrenceAtIndex = new int[K + 1];
        int[] lastSeen = new int[N + 1];
        Arrays.fill(lastSeen, INF);

        for (int i = K; i >= 1; i--) {
            int x = a[i];
            nextOccurrenceAtIndex[i] = lastSeen[x];
            lastSeen[x] = i;
        }

        boolean[] inCache = new boolean[N + 1];
        int[] currentNext = new int[N + 1];
        TreeSet<Node> set = new TreeSet<>();

        long ans = 0;
        int size = 0;

        for (int i = 1; i <= K; i++) {
            int x = a[i];

            if (inCache[x]) {
                set.remove(new Node(currentNext[x], x));
                currentNext[x] = nextOccurrenceAtIndex[i];
                set.add(new Node(currentNext[x], x));
            } else {
                ans += w[x];

                if (M > 0) {
                    if (size == M) {
                        Node evict = set.last(); // farthest next use
                        set.remove(evict);
                        inCache[evict.id] = false;
                        size--;
                    }

                    inCache[x] = true;
                    currentNext[x] = nextOccurrenceAtIndex[i];
                    set.add(new Node(currentNext[x], x));
                    size++;
                }
            }
        }

        System.out.println(ans);
    }
}
